action.query:
query GetAsset($where: AssetWhereInput) {
  query: asset(where: $where) {
    edges {
      node {
        id
        code
        name
        type
        subType
        manufacturer
        model
        serialNumber
        cellId
        cell { id code name }
        lineId
        line { id code name }
        deviceDriverId
        deviceDriver { id name }
        criticality
        status
        connectionString
        installedAt
        lastPmAt
        nextPmAt
        responsibleTeam
        createdAt
        createdByUser { id firstName lastName }
      }
    }
  }
}

